contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address who, uint256 v) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (v)); require(v <= 1000000000000000000000000000000);
        require(address(this).balance >= v);
        // establish prior balance
        uint256 before = c.getBalance(who); if (__ESBMC_reverted()) return;
        // perform the deposit as that user by sending value from this contract
        // (the contract calling will be msg.sender for C.addToBalance)
        // so we must ensure `who` is address(this) to observe the effect on the caller's balance
        require(who == address(this));
        c.addToBalance{value: v}(); if (__ESBMC_reverted()) return;
        uint256 afterBal = c.getBalance(who); if (__ESBMC_reverted()) return;
        // The real contract increases the caller's recorded balance by exactly the sent value v.
        assert(afterBal == before + v);
    }
    receive() external payable { }
}

