pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(address who, uint256 v) internal {
        v = bound(v, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= v);
        uint256 before;
        try c.getBalance(who) returns (uint256 __r) { before = __r; } catch { return; }
        who = address(this);
        try c.addToBalance{value: v}() {} catch { return; }
        uint256 afterBal;
        try c.getBalance(who) returns (uint256 __r) { afterBal = __r; } catch { return; }
        assertTrue(afterBal == before + v);
    }

    function testFuzz_run(address who, uint256 v) public {
        _run(who, v);
    }

    receive() external payable { }
}
